// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

// Module-level font loading ensures it's ready before frame 0
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type CinematicTimelineProps = Record<string, any>;

// Helper for realistic timecode generation
const formatTimecode = (totalFrames: number, fps: number) => {
  const f = Math.floor(totalFrames % fps);
  const s = Math.floor(totalFrames / fps) % 60;
  const m = Math.floor(totalFrames / (fps * 60)) % 60;
  const h = Math.floor(totalFrames / (fps * 3600));

  const pad = (n: number) => n.toString().padStart(2, "0");
  return `${pad(h)}:${pad(m)}:${pad(s)}:${pad(f)}`;
};

// Sub-components
const AudioWaveform: React.FC<{ height: number; delay: number }> = ({ height, delay }) => {
  const numBars = Math.min(Math.floor(height / 6), 80);
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: 2,
        width: "60%",
        height: "100%",
        opacity: 0.6,
      }}
    >
      {Array.from({ length: numBars }).map((_, i) => {
        const w = 20 + random(`wave-${delay}-${i}`) * 80;
        return (
          <div
            key={i}
            style={{
              height: 2,
              width: `${w}%`,
              backgroundColor: "#000",
              borderRadius: 0,
            }}
          />
        );
      })}
    </div>
  );
};

const Clip: React.FC<{
  clip: any;
  frame: number;
  delay: number;
  videoColors: string[];
  audioColors: string[];
  fps: number;
}> = ({ clip, frame, delay, videoColors, audioColors, fps }) => {
  const scale = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  if (scale === 0) return null;

  const colors = clip.colorType === "video" ? videoColors : audioColors;
  const color = colors[clip.colorIdx % colors.length];

  return (
    <div
      style={{
        position: "absolute",
        top: clip.y,
        left: 2,
        right: 2,
        height: clip.h,
        backgroundColor: color,
        borderRadius: 2,
        transform: `scaleY(${scale})`,
        transformOrigin: "top center",
        boxShadow: `inset 1px 1px 0 rgba(255,255,255,0.3), inset -1px -1px 0 rgba(0,0,0,0.2), 0 2px 4px ${color}40`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        padding: "8px 0",
        overflow: "hidden",
        opacity: interpolate(scale, [0, 1], [0, 0.95]),
      }}
    >
      {clip.colorType === "video" && clip.h > 120 && (
        <div
          style={{
            height: 20,
            width: "60%",
            backgroundColor: "rgba(0,0,0,0.3)",
            borderRadius: 2,
            marginBottom: 8,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            flexShrink: 0,
          }}
        >
          <div
            style={{
              width: 0,
              height: 0,
              borderTop: "3px solid transparent",
              borderBottom: "3px solid transparent",
              borderLeft: "5px solid rgba(255,255,255,0.6)",
            }}
          />
        </div>
      )}
      {clip.colorType === "video" ? (
        <div
          style={{
            fontSize: 10,
            fontWeight: 900,
            color: "rgba(0,0,0,0.5)",
            fontFamily: "sans-serif",
            letterSpacing: 1,
            writingMode: "vertical-rl",
            textOrientation: "mixed",
            whiteSpace: "nowrap",
          }}
        >
          SCENE_{Math.abs(Math.floor(clip.y))}
        </div>
      ) : (
        <AudioWaveform height={clip.h} delay={delay} />
      )}
    </div>
  );
};

const CinematicTimeline: React.FC<CinematicTimelineProps> = ({
  backgroundColor = "#08090d",
  transparentBackground = true,
  durationInSeconds = 10,
  playheadColor = "#00d8ff",
  videoTrackColors = ["#b933ff", "#3b82f6", "#8b5cf6"],
  audioTrackColors = ["#4ade80", "#f97316", "#eab308"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const durationFrames = durationInSeconds * fps;
  const INTRO_END = Math.min(60, durationFrames * 0.3);
  const TILT_END = Math.min(120, durationFrames * 0.5);

  const CANVAS_W = width;
  const CANVAS_H = height;
  const TIMELINE_W = 1000;
  const TIMELINE_H = 4000;
  const TRACKS_TOTAL_WIDTH = 660;

  // Generate deterministic tracks data for vertical layout
  const tracks = useMemo(() => {
    const t = [];
    const numTracks = 12;
    for (let i = 0; i < numTracks; i++) {
      const isVideo = i < 5;
      const trackWidth = isVideo ? 60 : 40;
      const clips = [];
      let y = 1000; // Start clips slightly down to allow playhead to scrub in
      for (let j = 0; j < 30; j++) {
        const h = 150 + random(`h-${i}-${j}`) * 400;
        const colorType = isVideo ? "video" : "audio";
        const colorIdx = Math.floor(random(`c-${i}-${j}`) * 3);
        clips.push({ y, h, colorType, colorIdx, idX: j, id: `${i}-${j}` });
        y += h + 10 + random(`g-${i}-${j}`) * 120;
      }
      t.push({ id: i, isVideo, width: trackWidth, clips });
    }
    return t;
  }, []);

  // Animation logic
  const cameraScale = interpolate(
    frame,
    [0, INTRO_END, TILT_END, durationFrames],
    [0.9, 1.1, 1.7, 1.9],
    { easing: Easing.out(Easing.cubic), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const rx = interpolate(frame, [INTRO_END, TILT_END], [0, 45], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const rz = interpolate(frame, [INTRO_END, TILT_END], [0, -5], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const scrollY = interpolate(
    frame,
    [INTRO_END, durationFrames],
    [0, -1200],
    { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const timelineCenter = TIMELINE_H / 2;
  const playheadOffset = interpolate(
    frame,
    [15, INTRO_END],
    [-400, 0],
    { easing: Easing.out(Easing.cubic), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const playheadVisualY = timelineCenter + playheadOffset;
  // Counteract the scroll so playhead stays anchored in visual space
  const playheadLocalY = playheadVisualY - scrollY;

  const playheadScale = spring({
    frame: frame - 10,
    fps,
    config: { damping: 15 },
  });

  const tcFrame = Math.floor(
    interpolate(frame, [15, durationFrames], [24300, 24300 + durationFrames * 2], {
      extrapolateLeft: "clamp",
    })
  );

  const bgStyle = transparentBackground ? {} : { backgroundColor };

  return (
    <AbsoluteFill style={{ ...bgStyle, perspective: 2500, overflow: "hidden" }}>
      {/* 3D Container */}
      <div
        style={{
          position: "absolute",
          left: CANVAS_W / 2 - TIMELINE_W / 2,
          top: CANVAS_H / 2 - TIMELINE_H / 2,
          width: TIMELINE_W,
          height: TIMELINE_H,
          transform: `scale(${cameraScale}) rotateX(${rx}deg) rotateZ(${rz}deg)`,
          transformStyle: "preserve-3d",
          display: "flex",
          flexDirection: "row",
          alignItems: "flex-start",
          justifyContent: "center",
        }}
      >
        {/* Scrolling Tracks Block */}
        <div
          style={{
            width: TRACKS_TOTAL_WIDTH,
            height: "100%",
            position: "relative",
            transform: `translateY(${scrollY}px)`,
          }}
        >
          {/* Time Ruler */}
          <div
            style={{
              width: 80,
              height: "100%",
              position: "absolute",
              top: 0,
              left: 0,
            }}
          >
            {Array.from({ length: 40 }).map((_, i) => (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top: i * 200,
                  right: 0,
                  width: 12,
                  height: 1,
                  backgroundColor: "rgba(255,255,255,0.4)",
                }}
              >
                <span
                  style={{
                    position: "absolute",
                    right: 16,
                    top: -7,
                    color: "rgba(255,255,255,0.6)",
                    fontSize: 12,
                    fontFamily: robotoMonoFamily,
                    letterSpacing: 1,
                  }}
                >
                  {formatTimecode(i * 200 * fps, fps)}
                </span>
              </div>
            ))}
          </div>

          {/* Tracks */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              marginLeft: 80,
              height: "100%",
              borderLeft: "1px solid rgba(255,255,255,0.15)",
            }}
          >
            {tracks.map((track) => (
              <div
                key={track.id}
                style={{
                  width: track.width,
                  position: "relative",
                  borderRight: "1px solid rgba(255,255,255,0.05)",
                  backgroundColor:
                    track.id % 2 === 0
                      ? "rgba(255,255,255,0.02)"
                      : "transparent",
                }}
              >
                {track.clips.map((clip) => (
                  <Clip
                    key={clip.id}
                    clip={clip}
                    frame={frame}
                    delay={15 + clip.idX * 1.5 + track.id * 2}
                    videoColors={videoTrackColors}
                    audioColors={audioTrackColors}
                    fps={fps}
                  />
                ))}
              </div>
            ))}
          </div>

          {/* Playhead */}
          <div
            style={{
              position: "absolute",
              top: playheadLocalY,
              left: -40,
              width: TRACKS_TOTAL_WIDTH + 80,
              zIndex: 100,
            }}
          >
            {/* The Line */}
            <div
              style={{
                width: "100%",
                height: 2,
                backgroundColor: playheadColor,
                boxShadow: `0 0 10px ${playheadColor}, 0 0 2px #fff`,
                transform: `scaleX(${playheadScale})`,
                transformOrigin: "left center",
              }}
            />
            
            {/* Playhead Left Marker */}
            <div
              style={{
                position: "absolute",
                left: -8,
                top: -9,
                width: 14,
                height: 20,
                backgroundColor: playheadColor,
                clipPath: "polygon(0 0, 100% 50%, 0 100%)",
                opacity: interpolate(playheadScale, [0, 0.5], [0, 1], { extrapolateRight: "clamp" }),
              }}
            />

            {/* Timecode Bubble */}
            <div
              style={{
                position: "absolute",
                left: 40,
                top: -34,
                backgroundColor: "#08090d",
                border: `1px solid ${playheadColor}80`,
                padding: "4px 8px",
                borderRadius: 2,
                color: playheadColor,
                fontFamily: robotoMonoFamily,
                fontSize: 14,
                fontWeight: "bold",
                letterSpacing: 1,
                boxShadow: "0 4px 10px rgba(0,0,0,0.8)",
                opacity: interpolate(playheadScale, [0.5, 1], [0, 1], { extrapolateLeft: "clamp" }),
              }}
            >
              {formatTimecode(tcFrame, fps)}
            </div>
          </div>
        </div>
      </div>

      {/* Cinematic Overlays */}
      {!transparentBackground && (
        <>
          <AbsoluteFill
            style={{
              pointerEvents: "none",
              background: "radial-gradient(circle at center, transparent 30%, rgba(0,0,0,0.85) 100%)",
              zIndex: 50,
            }}
          />
          <AbsoluteFill
            style={{
              mixBlendMode: "screen",
              pointerEvents: "none",
              zIndex: 100,
            }}
          >
            <div
              style={{
                position: "absolute",
                bottom: -300,
                left: -200,
                width: 1000,
                height: 1000,
                background: `radial-gradient(circle, ${playheadColor}15 0%, transparent 60%)`,
                filter: "blur(60px)",
              }}
            />
            <div
              style={{
                position: "absolute",
                top: -300,
                right: -200,
                width: 1000,
                height: 1000,
                background: `radial-gradient(circle, ${videoTrackColors[0]}15 0%, transparent 60%)`,
                filter: "blur(60px)",
              }}
            />
          </AbsoluteFill>
        </>
      )}
    </AbsoluteFill>
  );
};

export default CinematicTimeline;